param([Parameter(Mandatory=$true)][string]$Destination)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Speech
[System.IO.Directory]::CreateDirectory($Destination) | Out-Null
$specs=@(
 @{id='huihui';voice='Microsoft Huihui Desktop';name='慧慧 · 清朗女声';text='欢迎使用神思文档朗读。清晨的阳光穿过窗户，照亮桌上的书页。'},
 @{id='kangkang';voice='Microsoft Kangkang';name='康康 · 沉稳男声';text='欢迎使用神思文档朗读。清晨的阳光穿过窗户，照亮桌上的书页。'},
 @{id='yaoyao';voice='Microsoft Yaoyao';name='瑶瑶 · 温柔女声';text='欢迎使用神思文档朗读。清晨的阳光穿过窗户，照亮桌上的书页。'},
 @{id='zira';voice='Microsoft Zira Desktop';name='Zira · 英文女声';text='Welcome to Shensi. The morning sun shines through the window and lights up the pages of a book.'}
)
$result=@()
foreach($spec in $specs){
 $synth=New-Object System.Speech.Synthesis.SpeechSynthesizer
 try {
  $synth.SelectVoice($spec.voice)
  $path=Join-Path $Destination ($spec.id+'.wav')
  $synth.SetOutputToWaveFile($path)
  $synth.Speak($spec.text)
  $synth.SetOutputToNull()
  $result+=@{id=$spec.id;name=$spec.name;transcript=$spec.text;file=$path;available=$true;origin='local-windows-speech'}
 }catch{$result+=@{id=$spec.id;name=$spec.name;available=$false;reason='当前电脑没有此系统声音'}}finally{$synth.Dispose()}
}
$json=ConvertTo-Json -InputObject @($result) -Depth 4 -Compress
[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding($false)
[Console]::WriteLine($json)
